using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;
using WireMock.RequestBuilders;
using WireMock.ResponseBuilders;
using WireMock.Server;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly WireMockServer provider = WireMockServer.Start();
    private readonly HttpClient client;

    public HttpPaymentGatewayTests() => client = new HttpClient { BaseAddress = new Uri(provider.Url!) };

    [Fact]
    public async Task The_authorization_is_posted_as_json_with_reference_amount_and_currency()
    {
        provider.Given(Request.Create().WithPath("/v1/authorizations").UsingPost())
            .RespondWith(Response.Create().WithStatusCode(200).WithBody("""{"status":"approved"}"""));

        await new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        var received = Assert.Single(provider.LogEntries).RequestMessage;
        Assert.Equal("POST", received.Method);
        Assert.Equal("/v1/authorizations", received.Path);
        Assert.StartsWith("application/json", received.Headers!["Content-Type"].Single());
        using var json = JsonDocument.Parse(received.Body!);
        Assert.Equal(["amount", "currency", "reference"], json.RootElement.EnumerateObject().Select(p => p.Name).Order());
        Assert.Equal("ORD-7", json.RootElement.GetProperty("reference").GetString());
        Assert.Equal(12.5m, json.RootElement.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", json.RootElement.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Respond(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        Respond(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        Respond(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_payment_the_provider_refuses_with_402_is_declined()
    {
        Respond(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task A_request_the_provider_rejects_or_fails_is_an_error_not_a_decline(int status)
    {
        Respond(status, """{"error":"nope"}""");

        await Assert.ThrowsAsync<HttpRequestException>(Authorize);
    }

    [Fact]
    public async Task An_answer_that_is_not_json_is_an_error()
    {
        Respond(200, "<html>maintenance</html>");

        await Assert.ThrowsAsync<JsonException>(Authorize);
    }

    [Theory]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_answer_that_does_not_clearly_say_approved_is_never_approved(string body)
    {
        Respond(200, body);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    private void Respond(int status, string body) =>
        provider.Given(Request.Create().WithPath("/v1/authorizations").UsingPost())
            .RespondWith(Response.Create().WithStatusCode(status).WithHeader("Content-Type", "application/json").WithBody(body));

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12, "EUR"), CancellationToken.None);

    public void Dispose()
    {
        client.Dispose();
        provider.Dispose();
    }
}
